Core.Routing.IfElse-ybyg8.condition:
(() => {
    const THRESHOLD = $globalFields.compactionThreshold

    const g = $nodeGlobals

    for ( let i = $in.input.length - 1; i >= 0; i--){
        const msg = $in.input[i];

        if(msg && msg.type === "ai"){
            const tokens = msg.usage_metadata?.total_tokens ?? 0

            if(tokens > THRESHOLD && g.lastTokenSize !== tokens){
                // Save the number of messages before compaction
                g.lastTokenSize = tokens

                return true
            }
            break;
        }
    }

    return false;
})()
